import type { ProtectedResourceRef, ResourceGrant } from '@n8n/permissions';
import type { TrustedSource } from './trusted-source';
import type { SurfaceId } from './trusted-source-config';
export type Inbound = {
    surface: SurfaceId;
    resource: ProtectedResourceRef;
    acceptedSourceIds?: string[];
    grant?: ResourceGrant;
    request: {
        method: string;
        url: string;
        headers: Readonly<Record<string, string | string[] | undefined>>;
        ip: string;
    };
    receivedAt: Date;
};
export type Credential = {
    kind: 'bearer';
    token: string;
};
export type Extracted = Inbound & {
    credential: Credential;
};
export type Verified = Omit<Extracted, 'credential' | 'request'> & {
    request: Omit<Inbound['request'], 'headers'>;
    credentialKind: Credential['kind'];
    source: TrustedSource;
    claims: Readonly<Record<string, unknown>>;
    expiresAt: Date;
};
export type RejectReason = 'no-credential' | 'malformed-credential' | 'unknown-issuer' | 'source-not-accepted' | 'source-unusable' | 'signature-invalid' | 'expired' | 'revoked' | 'audience-mismatch' | 'not-an-access-token' | 'unknown-subject' | 'user-disabled' | 'binding-inactive' | 'link-refused' | 'provision-refused' | 'no-role';
export type ExternalIdentity = {
    subject: string;
    email?: string;
    emailVerified?: boolean;
    displayName?: string;
    clientId?: string;
    scopes: string[];
    assurance?: {
        acr?: string;
        amr?: string[];
        authTime?: Date;
    };
    raw: Readonly<Record<string, unknown>>;
};
export type Reject = {
    ok: false;
    reason: RejectReason;
    detail?: string;
};
export type Ok<T> = {
    ok: true;
    value: T;
};
export type Result<T> = Ok<T> | Reject;
